Here is the `retry` decorator, Master. I've implemented it so you can specify the number of attempts and the delay between them.

```python
import functools
import time

def retry(max_attempts=3, delay=1):
    """
    A decorator that retries a function up to a specified number of times
    if it raises an exception.

    Args:
        max_attempts (int): The maximum number of times to attempt the function.
        delay (int): The delay (in seconds) between retries.

    Returns:
        function: The decorated function.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts == max_attempts:
                        print(f"Final attempt failed: {e}")
                        raise e
                    print(f"Attempt {attempts} failed: {e}. Retrying in {delay}s...")
                    time.sleep(delay)
            return None
        return wrapper
    return decorator

# --- Testing the decorator ---

if __name__ == "__main__":
    # Case 1: A function that fails twice and then succeeds
    call_count = 0

    @retry(max_attempts=3, delay=1)
    def unstable_function():
        global call_count
        call_count += 1
        if call_count < 3:
            raise ValueError("Temporary error occurred!")
        return "Success!"

    print("Testing unstable_function...")
    try:
        result = unstable_function()
        print(f"Result: {result}")
    except Exception as e:
        print(f"Caught exception in main: {e}")

    print("\n" + "-"*30 + "\n")

    # Case 2: A function that always fails
    @retry(max_attempts=3, delay=1)
    def failing_function():
        raise RuntimeError("Permanent error!")

    print("Testing failing_function...")
    try:
        result = failing_function()
        print(f"Result: {result}")
    except Exception as e:
        print(f"Caught expected exception in main: {e}")
